def release_transfer_socket(sock)
  @transfer_runtime ||= {}
  @transfer_runtime[:released] = sock
  if sock
    sock.close_write rescue nil
    sock.close rescue nil
  end
end

def close_node_socket(manager, sock)
  @transfer_runtime ||= {}
  bind_transfer_manager(manager)
  cache = manager.instance_variable_get(:@socket_cache)
  if cache
    cache.checkin(sock)
  else
    release_transfer_socket(sock)
  end
end

